#!/usr/bin/env python3
"""Draws the flat SVG illustrations in public/img/transport (original artwork for this project).
Run once: python3 scripts/draw-transport-icons.py"""
from pathlib import Path

OUT = Path(__file__).resolve().parent.parent / 'public' / 'img' / 'transport'
OUT.mkdir(parents=True, exist_ok=True)

SKY = '<rect width="64" height="64" rx="8" fill="#cfe8ff"/>'
GROUND = lambda c='#9aa5b1', y=44: f'<rect x="0" y="{y}" width="64" height="{64 - y}" fill="{c}"/>'
ROAD = lambda y=40: f'<rect x="0" y="{y}" width="64" height="{64 - y}" fill="#4a4e57"/><rect x="0" y="{y + 10}" width="64" height="2" fill="#ffd54a" stroke-dasharray="6 4" stroke="#ffd54a"/>'
CAR = lambda x, y, c: f'<rect x="{x}" y="{y + 6}" width="22" height="9" rx="2" fill="{c}"/><rect x="{x + 4}" y="{y}" width="13" height="8" rx="2" fill="{c}"/><rect x="{x + 6}" y="{y + 1}" width="9" height="5" fill="#bde0fe"/><circle cx="{x + 5}" cy="{y + 15}" r="3" fill="#222"/><circle cx="{x + 17}" cy="{y + 15}" r="3" fill="#222"/>'
PERSON = lambda x, y, shirt='#e63946': f'<circle cx="{x}" cy="{y}" r="4" fill="#f5c6a5"/><rect x="{x - 4}" y="{y + 4}" width="8" height="11" rx="2" fill="{shirt}"/><rect x="{x - 3}" y="{y + 15}" width="2.5" height="8" fill="#222"/><rect x="{x + .5}" y="{y + 15}" width="2.5" height="8" fill="#222"/>'
CLOCK = lambda x, y, r=9: f'<circle cx="{x}" cy="{y}" r="{r}" fill="#fff" stroke="#333" stroke-width="2"/><line x1="{x}" y1="{y}" x2="{x}" y2="{y - r * .6}" stroke="#333" stroke-width="2"/><line x1="{x}" y1="{y}" x2="{x + r * .5}" y2="{y}" stroke="#e63946" stroke-width="2"/>'
TRAIN = lambda y=30, c='#1d3557': f'<rect x="4" y="{y}" width="56" height="16" rx="3" fill="{c}"/>' + ''.join(f'<rect x="{9 + i * 12}" y="{y + 3}" width="8" height="6" fill="#bde0fe"/>' for i in range(4)) + f'<circle cx="14" cy="{y + 18}" r="3" fill="#222"/><circle cx="50" cy="{y + 18}" r="3" fill="#222"/>'

ICONS = {
    'parking-lot': SKY + '<rect x="0" y="20" width="64" height="44" fill="#4a4e57"/>' + ''.join(f'<rect x="{6 + i * 14}" y="20" width="2" height="44" fill="#fff"/>' for i in range(5)) + CAR(9, 26, '#e63946') + CAR(37, 44, '#4d96ff') + '<rect x="4" y="4" width="14" height="14" rx="2" fill="#1d3557"/><text x="11" y="15" font-family="sans-serif" font-size="11" font-weight="bold" fill="#fff" text-anchor="middle">P</text>',
    'commuter': SKY + GROUND('#7c8a99', 50) + PERSON(24, 14, '#2b3a67') + '<rect x="30" y="26" width="10" height="12" rx="1" fill="#8d5524"/><rect x="33" y="24" width="4" height="3" fill="#5a2d1a"/><rect x="44" y="8" width="16" height="12" rx="2" fill="#fff"/><text x="52" y="17" font-family="sans-serif" font-size="8" fill="#333" text-anchor="middle">8:15</text>',
    'delayed': SKY + GROUND('#7c8a99', 50) + TRAIN(32) + CLOCK(46, 14, 10) + '<rect x="6" y="6" width="26" height="14" rx="2" fill="#e63946"/><text x="19" y="16" font-family="sans-serif" font-size="7" font-weight="bold" fill="#fff" text-anchor="middle">DELAYED</text>',
    'on-time': SKY + GROUND('#7c8a99', 50) + TRAIN(32, '#2e7d32') + CLOCK(46, 14, 10) + '<circle cx="16" cy="14" r="9" fill="#2e7d32"/><path d="M11 14 L15 18 L22 10" stroke="#fff" stroke-width="3" fill="none" stroke-linecap="round"/>',
    'parking-space': SKY + '<rect x="0" y="12" width="64" height="52" fill="#4a4e57"/><rect x="10" y="14" width="2" height="48" fill="#fff"/><rect x="52" y="14" width="2" height="48" fill="#fff"/><rect x="10" y="14" width="44" height="2" fill="#fff"/><text x="32" y="46" font-family="sans-serif" font-size="26" font-weight="bold" fill="#fff" text-anchor="middle" opacity=".8">P</text>' + CAR(21, 18, '#4d96ff'),
    'passenger': SKY + '<rect x="6" y="14" width="52" height="36" rx="4" fill="#4d96ff"/><rect x="10" y="18" width="44" height="14" fill="#bde0fe"/><circle cx="20" cy="26" r="4" fill="#f5c6a5"/><rect x="16" y="30" width="8" height="4" fill="#e63946"/><circle cx="36" cy="26" r="4" fill="#f5c6a5"/><rect x="32" y="30" width="8" height="4" fill="#ffd54a"/><circle cx="16" cy="52" r="5" fill="#222"/><circle cx="48" cy="52" r="5" fill="#222"/>',
    'platform': SKY + '<rect x="0" y="40" width="64" height="24" fill="#4a4e57"/><rect x="0" y="44" width="64" height="2" fill="#333"/><rect x="0" y="54" width="64" height="2" fill="#333"/>' + ''.join(f'<rect x="{2 + i * 8}" y="42" width="3" height="16" fill="#8d5524"/>' for i in range(8)) + '<rect x="0" y="30" width="64" height="10" fill="#c8ccd2"/><rect x="0" y="38" width="64" height="2" fill="#ffd54a"/>' + PERSON(20, 8, '#e63946') + '<rect x="40" y="10" width="18" height="10" rx="1" fill="#1d3557"/><text x="49" y="18" font-family="sans-serif" font-size="7" fill="#fff" text-anchor="middle">2</text>',
    'public-transportation': SKY + ROAD(46) + '<rect x="6" y="14" width="52" height="32" rx="4" fill="#f4a261"/><rect x="10" y="18" width="44" height="12" fill="#bde0fe"/>' + ''.join(f'<rect x="{11 + i * 11}" y="18" width="1.5" height="12" fill="#f4a261"/>' for i in range(4)) + '<rect x="10" y="34" width="44" height="6" fill="#e76f51"/><text x="32" y="39" font-family="sans-serif" font-size="5" font-weight="bold" fill="#fff" text-anchor="middle">BUS</text><circle cx="16" cy="48" r="5" fill="#222"/><circle cx="48" cy="48" r="5" fill="#222"/>',
    'rush-hour': SKY + ROAD(30) + CAR(2, 36, '#e63946') + CAR(24, 36, '#ffd54a') + CAR(46, 36, '#4d96ff') + CLOCK(32, 14, 10) + '<text x="10" y="18" font-family="sans-serif" font-size="8" font-weight="bold" fill="#e63946">5:30</text>',
    'traffic-jam': SKY + ROAD(20) + CAR(4, 22, '#e63946') + CAR(30, 22, '#4d96ff') + CAR(-6, 44, '#ffd54a') + CAR(18, 44, '#2e7d32') + CAR(42, 44, '#9c27b0') + '<path d="M12 12 L12 8" stroke="#333" stroke-width="2"/><text x="46" y="14" font-family="sans-serif" font-size="9" font-weight="bold" fill="#e63946" text-anchor="middle">!!!</text>',
    'subway': '<rect width="64" height="64" rx="8" fill="#333"/><path d="M6 50 L6 30 A26 26 0 0 1 58 30 L58 50Z" fill="#555"/>' + TRAIN(34, '#e63946') + '<rect x="4" y="50" width="56" height="4" fill="#777"/><circle cx="32" cy="14" r="8" fill="#fff"/><text x="32" y="18" font-family="sans-serif" font-size="11" font-weight="bold" fill="#e63946" text-anchor="middle">M</text>',
    'taxi': SKY + ROAD(44) + '<rect x="8" y="30" width="48" height="14" rx="3" fill="#ffd54a"/><rect x="16" y="20" width="30" height="12" rx="3" fill="#ffd54a"/><rect x="19" y="22" width="11" height="8" fill="#bde0fe"/><rect x="33" y="22" width="10" height="8" fill="#bde0fe"/><rect x="25" y="14" width="14" height="6" rx="1" fill="#333"/><text x="32" y="19" font-family="sans-serif" font-size="5" font-weight="bold" fill="#ffd54a" text-anchor="middle">TAXI</text><circle cx="18" cy="46" r="5" fill="#222"/><circle cx="46" cy="46" r="5" fill="#222"/>',
    'miss-the-bus': SKY + ROAD(46) + '<rect x="30" y="16" width="34" height="30" rx="4" fill="#f4a261"/><rect x="34" y="20" width="26" height="10" fill="#bde0fe"/><circle cx="38" cy="48" r="5" fill="#222"/><circle cx="58" cy="48" r="5" fill="#222"/>' + PERSON(14, 14, '#e63946') + '<path d="M20 26 L28 22" stroke="#f5c6a5" stroke-width="3" stroke-linecap="round"/><path d="M24 8 L26 4 M28 10 L31 8" stroke="#333" stroke-width="1.5"/>',
    'bike-ride': SKY + GROUND('#7cb342', 48) + '<circle cx="16" cy="44" r="9" stroke="#333" stroke-width="3" fill="none"/><circle cx="48" cy="44" r="9" stroke="#333" stroke-width="3" fill="none"/><path d="M16 44 L26 28 L40 28 L48 44 M26 28 L34 44 L16 44" stroke="#e63946" stroke-width="3" fill="none"/><path d="M40 28 L38 22 M22 26 L30 26" stroke="#333" stroke-width="2.5"/>' + PERSON(34, 8, '#4d96ff'),
}

for name, body in ICONS.items():
    svg = f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64">{body}</svg>'
    (OUT / f'{name}.svg').write_text(svg)
print(f'wrote {len(ICONS)} icons to {OUT}')
